(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit31-world-examples-advanced"]={"id":"unit31-world-examples-advanced","unitId":"3-1","chapterIds":["3-1"],"unitType":"advanced","group":"3-1단원 · 4. 넓어지는 사랑과 실천","name":"웹의 쉬운 축구 예시 · 심화 5지선다","level":"심화","revision":1,"originPage":"unit31","shuffleQuestions":true,"timedMode":"question","parts":[{"name":"U31-E08 · 둘이서만 주고받는 패스","items":[{"paragraphCount":2,"readingLabel":"15문단 · 새 예시 적용","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 15문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 15문단]\n따라서 성숙한 사랑은 ‘한’ 사람 내지, ‘하나의’ 대상에 대한 태도가 아니라 세계 전체와의 관계를 결정하는 ‘태도’, 곧 ‘특정한 성격’이다. 어떤 사람을 진정 사랑한다는 것은 그 사람의 인간적인 핵심, 즉 인류와 삶을 대표하는 자로서의 그 사람과 관계하는 것을 의미한다. 어떤 개인에 대한 사랑이 인류에 대한 사랑과 분리되어 있는 한, 그 개인에 대한 사랑이란 다만 피상적인 것일 뿐이며 확대된 이기주의일 뿐이다. 진정한 의미의 사랑은 자신의 자율성과 독립성을 상실하지 않은 채 다른 사람과 모든 인류 그리고 자연과의 결합을 경험하는 것이다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n하준과 서진은 친해서 둘이서만 패스를 주고받는다. 다른 동료에게는 공이 가지 않아 둘은 즐겁지만 팀은 무너진다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["조건"],"why":"두 선수는 서로만 챙기고 다른 동료는 생각하지 않는다. 한 사람만 사랑하고 다른 사람들의 삶에는 관심을 끊는 것을 글쓴이는 이기적인 사랑이라고 본다.\n근거: “어떤 개인에 대한 사랑이 인류에 대한 사랑과 분리되어 있는 한, 그 개인에 대한 사랑이란 다만 피상적인 것일 뿐이며 확대된 이기주의일 뿐이다.”\n15문단에서 확인할 수 있어요.","evidence":{"title":"둘이서만 주고받는 패스","statement":"두 선수는 다른 동료를 생각하지 않고 둘만 챙긴다. 다른 사람들에게 관심 없이 둘만 사랑하는 모습과 같다.","explanation":"두 선수는 서로만 챙기고 다른 동료는 생각하지 않는다. 한 사람만 사랑하고 다른 사람들의 삶에는 관심을 끊는 것을 글쓴이는 이기적인 사랑이라고 본다.\n근거: “어떤 개인에 대한 사랑이 인류에 대한 사랑과 분리되어 있는 한, 그 개인에 대한 사랑이란 다만 피상적인 것일 뿐이며 확대된 이기주의일 뿐이다.”\n15문단에서 확인할 수 있어요.","valid":["R15:3"],"sources":[{"id":"R15","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"15문단","sentences":[{"id":"R15:1","text":"따라서 성숙한 사랑은 ‘한’ 사람 내지, ‘하나의’ 대상에 대한 태도가 아니라 세계 전체와의 관계를 결정하는 ‘태도’, 곧 ‘특정한 성격’이다.","paragraph":0,"memberIds":["R15:1"],"topic":"그러니 성숙한 사랑은 '한' 사람, '하나의' 대상을 대하는 태도가 아니다. 세상 전체와 어떻게 관계를 맺을지 정하는 '태도', 곧 그 사람이 가진 '특정한 성격'이다."},{"id":"R15:2","text":"어떤 사람을 진정 사랑한다는 것은 그 사람의 인간적인 핵심, 즉 인류와 삶을 대표하는 자로서의 그 사람과 관계하는 것을 의미한다.","paragraph":0,"memberIds":["R15:2"],"topic":"어떤 사람을 진짜로 사랑한다는 것은 그 사람의 인간으로서의 핵심과 관계를 맺는 것이다. 즉 그 사람을 '인류와 삶을 대표하는 한 사람'으로 대하는 것이다."},{"id":"R15:3","text":"어떤 개인에 대한 사랑이 인류에 대한 사랑과 분리되어 있는 한, 그 개인에 대한 사랑이란 다만 피상적인 것일 뿐이며 확대된 이기주의일 뿐이다.","paragraph":0,"memberIds":["R15:3"],"topic":"한 사람에 대한 사랑이 인류(모든 사람)에 대한 사랑과 따로 떨어져 있다면, 그 사랑은 겉만 보는(피상적인) 것일 뿐이다. 나만 챙기던 마음이 '우리'만 챙기는 마음으로 넓어진 것(확대된 이기주의)일 뿐이다."},{"id":"R15:4","text":"진정한 의미의 사랑은 자신의 자율성과 독립성을 상실하지 않은 채 다른 사람과 모든 인류 그리고 자연과의 결합을 경험하는 것이다.","paragraph":0,"memberIds":["R15:4"],"topic":"진짜 사랑은 스스로 정하는 힘(자율성)과 남에게 기대지 않는 성질(독립성)을 잃지 않으면서, 다른 사람·모든 인류·자연과 하나로 이어지는(결합) 경험을 하는 것이다."}]}]},"examplePractice":true,"id":"U31-E08-S1","type":"mc","sent":"지문을 바탕으로 새 축구 예시를 바르게 설명한 것은?","options":["두 선수는 다른 동료를 생각하지 않고 둘만 챙긴다. 다른 사람들에게 관심 없이 둘만 사랑하는 모습과 같다.","두 선수는 다른 동료를 생각하며 모두를 챙긴다. 세상 전체를 사랑하는 성숙한 모습과 같다.","성숙한 사랑은 특정한 한 사람만 대하는 태도다. 세상 전체와는 관계가 없다.","어떤 사람을 진정으로 사랑할 때는 그 사람과만 관계를 맺으며 다른 사람들의 삶에는 관심을 두지 않는다.","한 사람을 좋아하면서 다른 사람들의 삶에는 관심이 없어도, 그 사랑은 성숙한 사랑이다."],"answer":"두 선수는 다른 동료를 생각하지 않고 둘만 챙긴다. 다른 사람들에게 관심 없이 둘만 사랑하는 모습과 같다.","requiresEvidence":true,"choiceReviews":{"두 선수는 다른 동료를 생각하지 않고 둘만 챙긴다. 다른 사람들에게 관심 없이 둘만 사랑하는 모습과 같다.":{"reason":"두 선수는 서로만 챙기고 다른 동료는 생각하지 않는다. 한 사람만 사랑하고 다른 사람들의 삶에는 관심을 끊는 것을 글쓴이는 이기적인 사랑이라고 본다.\n근거: “어떤 개인에 대한 사랑이 인류에 대한 사랑과 분리되어 있는 한, 그 개인에 대한 사랑이란 다만 피상적인 것일 뿐이며 확대된 이기주의일 뿐이다.”\n15문단에서 확인할 수 있어요.","edits":[]},"두 선수는 다른 동료를 생각하며 모두를 챙긴다. 세상 전체를 사랑하는 성숙한 모습과 같다.":{"reason":"두 선수는 서로만 챙기고 다른 동료는 생각하지 않는다. 한 사람만 사랑하고 다른 사람들의 삶에는 관심을 끊는 것을 글쓴이는 이기적인 사랑이라고 본다.\n근거: “어떤 개인에 대한 사랑이 인류에 대한 사랑과 분리되어 있는 한, 그 개인에 대한 사랑이란 다만 피상적인 것일 뿐이며 확대된 이기주의일 뿐이다.”\n15문단에서 확인할 수 있어요.","edits":[{"start":13,"end":22,"before":"생각하며 모두를 ","after":"생각하지 않고 둘만 "},{"start":27,"end":34,"before":"세상 전체를 ","after":"다른 사람들에게 관심 없이 둘만 "},{"start":39,"end":43,"before":"성숙한 ","after":""}]},"성숙한 사랑은 특정한 한 사람만 대하는 태도다. 세상 전체와는 관계가 없다.":{"reason":"성숙한 사랑은 세상 전체를 대하는 태도다. 특정한 한 사람에게만 향하는 감정이 아니다.\n근거: “따라서 성숙한 사랑은 ‘한’ 사람 내지, ‘하나의’ 대상에 대한 태도가 아니라 세계 전체와의 관계를 결정하는 ‘태도’, 곧 ‘특정한 성격’이다.”\n15문단에서 확인할 수 있어요.","edits":[{"start":4,"end":8,"before":"사랑은 ","after":"사랑은 세상 전체를 대하는 태도다. "},{"start":14,"end":42,"before":"사람만 대하는 태도다. 세상 전체와는 관계가 없다.","after":"사람에게만 향하는 감정이 아니다."}]},"어떤 사람을 진정으로 사랑할 때는 그 사람과만 관계를 맺으며 다른 사람들의 삶에는 관심을 두지 않는다.":{"reason":"글쓴이는 상대의 '인간적인 핵심'과 관계한다고 말했다. 그 사람을 인류와 삶을 대표하는 한 사람으로 보고 사랑한다는 뜻이다. 그래서 한 사람을 사랑하는 일을 다른 사람들의 삶과 따로 떼어 보지 않는다.\n근거: “어떤 사람을 진정 사랑한다는 것은 그 사람의 인간적인 핵심, 즉 인류와 삶을 대표하는 자로서의 그 사람과 관계하는 것을 의미한다.”\n15문단에서 확인할 수 있어요.","edits":[{"start":21,"end":26,"before":"사람과만 ","after":"사람을 인류와 삶을 대표하는 한 사람으로 보고 "},{"start":30,"end":57,"before":"맺으며 다른 사람들의 삶에는 관심을 두지 않는다.","after":"맺는다."}]},"한 사람을 좋아하면서 다른 사람들의 삶에는 관심이 없어도, 그 사랑은 성숙한 사랑이다.":{"reason":"한 사람을 좋아하면서 다른 사람들의 삶에는 관심이 없다면, 그 사랑은 깊이 없는 사랑이다.\n근거: “어떤 개인에 대한 사랑이 인류에 대한 사랑과 분리되어 있는 한, 그 개인에 대한 사랑이란 다만 피상적인 것일 뿐이며 확대된 이기주의일 뿐이다.”\n15문단에서 확인할 수 있어요.","edits":[{"start":28,"end":33,"before":"없어도, ","after":"없다면, "},{"start":39,"end":43,"before":"성숙한 ","after":"깊이 없는 "}]}},"pageSpecificReasons":true,"editorSourceVersion":"1559a0dc5b4a1ebc18572697e9eca4950e70c5543daf946bd3be9c37ebda6e32"}]}],"readingBlock":"world","readingChunk":"examples"};})(window);
